async () => {
  // Calculate date 30 days ago from today (2026-09-23)
  const today = new Date('2026-09-23');
  const thirtyDaysAgo = new Date(today);
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
  const cutoffDate = thirtyDaysAgo.toISOString().split('T')[0]; // YYYY-MM-DD format

  console.log(`Searching for open issues in Web project updated before ${cutoffDate}`);

  // Search for stale issues
  const issues = await connecta.call('tracker.search_issues', {
    project: 'web',
    status: 'open',
    updatedBefore: cutoffDate,
    limit: 50
  });

  console.log(`Found ${issues.issues.length} stale open issues`);

  if (issues.issues.length === 0) {
    console.log('No stale issues to close');
    return { closedKeys: [] };
  }

  // Close each issue
  const closedKeys = [];
  for (const issue of issues.issues) {
    console.log(`Closing ${issue.id}`);
    await connecta.call('tracker.close_issue', {
      id: issue.id,
      comment: 'Automatically closed due to inactivity (no updates in 30+ days)'
    });
    closedKeys.push(issue.id);
  }

  console.log(`\nClosed ${closedKeys.length} issues:`, closedKeys.join(', '));

  // Post summary to #eng channel
  const message = `Closed ${closedKeys.length} stale issues from Web project (no updates in 30+ days):\n${closedKeys.join(', ')}`;
  await connecta.call('chat.post_message', {
    channel: '#eng',
    text: message
  });

  console.log('Posted summary to #eng');
  return { closedKeys };
};

