async () => {
  const r = await connecta.call("ci.get_run_log", { runId: 4812 });
  const text = typeof r === "string" ? r : JSON.stringify(r);
  const lines = text.split(/\r?\n|\\n/);
  const hits = lines.map((l,i)=>[i,l]).filter(([i,l]) => /fail|retry|pass|error|exit|✗|✓|FAIL|PASS/i.test(l));
  return { type: typeof r, keys: r && typeof r === "object" ? Object.keys(r) : null, totalLines: lines.length, hits: hits.slice(0,200), tail: lines.slice(-30) };
}

async () => {
