async () => {
  const connecta = globalThis.connecta;

  // Find Northwind Traders customer
  const customerResult = await connecta.call("billing.find_customer", { query: "Northwind Traders" });
  const customers = customerResult;

  if (!customers || customers.length === 0) {
    return { error: "Northwind Traders not found" };
  }

  const customerId = customers[0].id;

  // Get unpaid invoices (open and past_due)
  const openInvoices = await connecta.call("billing.list_invoices", { customerId, status: "open" });
  const pastDueInvoices = await connecta.call("billing.list_invoices", { customerId, status: "past_due" });

  // Calculate totals
  const openTotal = (openInvoices || []).reduce((sum, inv) => sum + (inv.amount || 0), 0);
  const pastDueTotal = (pastDueInvoices || []).reduce((sum, inv) => sum + (inv.amount || 0), 0);
  const grandTotal = openTotal + pastDueTotal;

  return {
    customerId,
    openInvoices: openInvoices || [],
    pastDueInvoices: pastDueInvoices || [],
    openTotal,
    pastDueTotal,
    grandTotal
  };
}

