const run = async () => {
  // 1. list all accounts (paged)
  let accounts = [];
  let cursor = undefined;
  do {
    const res = await connecta.call("analytics.list_accounts", cursor ? { limit: 25, cursor } : { limit: 25 });
    accounts = accounts.concat(res.accounts || res.items || res.data || []);
    cursor = res.cursor || res.nextCursor || null;
    if (!res.accounts && !res.items && !res.data) {
      return { sample: res };
    }
  } while (cursor);

  // 2. get metrics for each account (MRR)
  const metricsResults = await Promise.allSettled(
    accounts.map(a => connecta.call("analytics.get_account_metrics", { accountId: a.id }))
  );

  const withMrr = accounts.map((a, i) => {
    const m = metricsResults[i];
    return {
      id: a.id,
      name: a.name,
      metrics: m.status === "fulfilled" ? m.value : null,
      error: m.status === "rejected" ? String(m.reason) : null
    };
  });

  return { count: accounts.length, sample: withMrr.slice(0, 3), all: withMrr };
};
return await run();

