async () => {
  const result = await connecta.call('ci.get_run_log', { runId: 4812 });
  const lines = result.split('\n');

  // Find all FAILED lines
  const failedTests = [];
  const testStatus = {};

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Match FAILED pattern
    if (line.includes('FAILED')) {
      const match = line.match(/FAILED\s+([^\s]+\.test\.[tj]s)/);
      if (match) {
        const testFile = match[1];
        failedTests.push({ line: i, file: testFile, text: line });
        if (!testStatus[testFile]) {
          testStatus[testFile] = [];
        }
        testStatus[testFile].push({ line: i, status: 'FAILED' });
      }
    }

    // Also track PASS to see if a test was retried
    if (line.includes('PASS')) {
      const match = line.match(/PASS\s+([^\s]+\.test\.[tj]s)/);
      if (match) {
        const testFile = match[1];
        if (!testStatus[testFile]) {
          testStatus[testFile] = [];
        }
        testStatus[testFile].push({ line: i, status: 'PASS' });
      }
    }
  }

  console.log('=== FAILED TESTS FOUND ===');
  console.log(`Total FAILED entries: ${failedTests.length}`);

  // Show which tests failed and their final status
  console.log('\n=== TEST STATUS (last status is final) ===');
  for (const [testFile, statuses] of Object.entries(testStatus)) {
    if (statuses.some(s => s.status === 'FAILED')) {
      const lastStatus = statuses[statuses.length - 1];
      console.log(`${testFile}: ${lastStatus.status} (line ${lastStatus.line})`);
      if (lastStatus.status === 'FAILED') {
        console.log(`  ^ This test failed and did NOT pass on retry`);
      }
    }
  }

  // Look at the end of the log for the final result
  console.log('\n=== END OF LOG (last 20 lines) ===');
  for (let i = Math.max(0, lines.length - 20); i < lines.length; i++) {
    console.log(lines[i]);
  }

  return { failedTests: failedTests.map(t => t.file), finalStatuses: testStatus };
}

